function updatePlayer(){const s=$('#answerstatus');if(!s)return;const me=state.players.find(p=>p.id===playerId);if(state.phase==='question'){s.textContent=state.solo?(me?.answered?'✓ Respuesta recibida.':'Responde antes de que termine el tiempo.'):canPlay()&&me?.answered?'✓ Respuesta recibida. Espera al resto de jugadores.':state.answered+' de '+state.players.length+' jugadores han respondido.';if(canPlay()&&me?.answered){const a=$('#answers');if(a&&!a.dataset.locked){a.dataset.locked='1';a.removeAttribute('aria-busy');a.replaceChildren(makeAnswerReceipt(me));}}}}
