function tick(){const audible=role==='screen'||(state?.solo&&role==='host');updateShowAudio(audible&&view===role&&!document.hidden?state:null,offset);if(!state)return;const c=$('#clock'),bar=$('#timebar');if(!c||!bar)return;if(state.partyStage==='intro'){const left=Math.max(0,state.deadline-Date.now()-offset),n=Math.max(0,Math.ceil(left/1000)),label=n?String(n):'¡YA!';if(c.textContent!==label){c.textContent=label;c.parentElement.dataset.count=label;}const fraction=Math.max(0,Math.min(1,left/(state.introDuration||3000)));c.parentElement.style.setProperty('--count-progress',String(fraction*100)+'%');bar.setAttribute('progress',String(fraction*100));return;}if(state.partyStage==='reflex-wait'){c.textContent='…';bar.setAttribute('progress','100');return;}const left=state.phase==='question'?Math.max(0,state.deadline-Date.now()-offset):0;const display=state.phase==='question'?Math.ceil(left/1000)+'s':'FIN';if(c.textContent!==display)c.textContent=display;const urgent=state.phase==='question'&&left>0&&left<=5000; c.classList.toggle('urgent',urgent);root.classList.toggle('show-urgent',urgent);const seconds=({'draw':45,'memory-show':state.question?.party==='count'?2.3:3.2,'reflex-wait':5,'reflex-go':7, 'bluff-write':25,'bluff-vote':20,'hot-answer':9,'hot-pass':6,'pie-target':8 })[state.partyStage]|| (state.partyStage==='bet'?12:state.question?.party==='buzzer'?(state.partyStage==='buzz'?25:7):state.question.seconds);const value=String(Math.max(0,Math.min(100,100*left/(seconds*1000))));if(bar.getAttribute('progress')!==value)bar.setAttribute('progress',value);}
setInterval(tick,150);
function metric(parent,label,value,extra){const box=el('div','stat');box.append(el('small','',label),el('strong','',value),el('span','',extra));parent.append(box);}
function bars(title,rows,labels={},kind=''){const box=panel();box.append(el('h3','',title));if(!rows.length)box.append(el('p','empty','Todavía no hay datos.'));for(const r of rows){const line=el('div','bar-row'),head=el('div'),name=el('span','',kind==='category'?'':labels[r.name]||r.name);if(kind==='category'){line.classList.add('category-stat');line.style.setProperty('--stat-color',categoryArt(r.name).color);name.append(categoryBadge(r.name));}name.append(el('small','',' · '+r.correct+'/'+r.total));head.append(name,el('strong','',r.accuracy+'%'));const bar=el('div','bar'),fill=el('i');fill.style.width=Math.max(0,Math.min(100,r.accuracy))+'%';bar.setAttribute('role','meter');bar.setAttribute('aria-label',r.name);bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax','100');bar.setAttribute('aria-valuenow',String(r.accuracy));bar.append(fill);line.append(head,bar);if(r.avgMs!==null)line.append(el('small','',(r.avgMs/1000).toFixed(1)+' s de media'));box.append(line);}return box;}
async function profile(){if(!user){login(profile);return;}setView('profile');const current=state;root.append(el('p','sub','Cargando tus estadísticas…'));try{const {stats:s,officialStats:official,user:u,progression:progress}=await api('/api/me');if(view!=='profile')return;user=u;navProgress=progress;navProgressUser=u.id;navRender();root.replaceChildren();heading(root,'TU CARRERA','Estadísticas de '+u.name,u.guest?'Perfil de invitado: conserva este navegador para acceder a tus estadísticas.':'Tus resultados están vinculados a tu cuenta de Google.');const identity=el('div','profile-identity');identity.append(avatarNode(u.avatar,u.name));if(!state||state.phase==='lobby'&&canPlay())identity.append(button('Personalizar personaje','secondary',openWardrobe));identity.append(button('Mis emotes','secondary',()=>emoteSettings(u,progress)));root.append(identity);mountCharacter(identity,u.avatar,'idle');if(progress)root.append(progressionPanel(progress));const metrics=el('div','stat-grid');metric(metrics,'Aciertos',s.total?s.accuracy+'%':'—',s.correct+' de '+s.total+' preguntas');metric(metrics,'Partidas ganadas',String(s.wins),s.matches+' partidas terminadas');metric(metrics,'Tiempo de respuesta',s.avgMs===null?'—':(s.avgMs/1000).toFixed(1)+' s','Media de respuestas enviadas');metric(metrics,'Récord oficial',(official?.bestScore??0).toLocaleString('es-ES'),(official?.matches??0)+' partidas oficiales');metric(metrics,'Récord personal',s.bestScore.toLocaleString('es-ES'),'Incluye partidas personalizadas');root.append(metrics);const grid=el('div','stats-grid');grid.append(bars('Rendimiento por categoría',s.byCategory,{},'category'),bars('Rendimiento por prueba',s.byMode,modes),bars('Rendimiento por formato',s.byMedia,mediaNames),bars('Rendimiento por dificultad',s.byDifficulty));const trend=panel();trend.append(el('h3','','Evolución de aciertos'));if(!s.trend.length)trend.append(el('p','empty','Juega para empezar a ver tu progreso.'));else{const chart=el('div','trend');for(const r of s.trend){const col=el('div'),fill=el('i');fill.style.height=r.accuracy+'%';fill.title=r.name+': '+r.accuracy+'%';col.append(el('small','',r.accuracy+'%'),fill,el('small','',r.name.slice(5)));chart.append(col);}trend.append(chart);}grid.append(trend);const recent=panel();recent.append(el('h3','','Últimas partidas'));for(const m of s.recent){const row=el('div','rank-row');row.append(el('span','name',new Date(m.at).toLocaleDateString('es-ES')+' · '+(m.solo?'Individual':m.win?'Victoria':'Partida')),el('strong','',m.score.toLocaleString('es-ES')+' pts'));recent.append(row);}if(!s.recent.length)recent.append(el('p','empty','Todavía no has terminado una partida.'));grid.append(recent);root.append(grid,button('Cerrar sesión','ghost',()=>{if(state&&role&&!confirm('¿Quieres salir del concurso?'))return;logout();}),button('Eliminar mi cuenta','ghost',async()=>{if(!confirm('¿Eliminar definitivamente tu perfil y estadísticas?'))return;try{await api('/api/delete-account',{});await logout();}catch(e){toast(e.message);}}),button(current&&role?'Volver a la sala':'Volver al inicio','ghost',()=>{if(current&&role){state=state||current;renderRoom();}else home();}));}catch(e){root.replaceChildren(el('p','error',e.message),button(state&&role?'Volver al concurso':'Volver','ghost',()=>state&&role?renderRoom():home()));}}
async function boot(){if(token){try{const me=await api('/api/me');user=me.user;navProgress=me.progression;navProgressUser=user.id;}catch{token='';localStorage.removeItem('mq.token');}}navRender();if(params.has('screen')){setView('screen');role='screen';preloadPresenter();if(params.get('cast')==='1'){window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===window.parent&&e.data?.type==='mq-tv-audio'){setMusicEnabled(e.data.music);setSoundEnabled(e.data.sound);if(!e.data.sound)stopPresenter();unlockAudio();}});}unlockAudio();navRender();root.append(el('p','sub','Conectando a la pantalla del concurso…'));await joinRoom(params.get('screen'),'screen');}else if(params.has('host')){const c=params.get('host');ensure(()=>joinRoom(c,'host'));}else if(params.has('join')){const c=params.get('join');ensure(()=>joinForm(c));}else home();}
boot();

function progressionPanel(p){const section=el('section','career-progress panel');const top=el('div','career-level');top.append(el('strong','','NIVEL '+p.level),el('span','',p.xp.toLocaleString('es-ES')+' XP · '+p.levelXp+' / '+p.nextLevelXp));const meter=el('mq-round-meter');meter.setAttribute('progress',String(p.levelXp/p.nextLevelXp*100));section.append(top,meter,el('h3','','Colección de logros'));const list=el('div','achievements');for(const a of p.achievements){const item=el('article','achievement'+(a.unlocked?' unlocked':''));item.append(el('b','',a.unlocked?'✓ '+a.name:a.name),el('span','',a.description),el('small','',a.progress+' / '+a.target+' · '+a.label));list.append(item);}section.append(list,el('p','footnote','La experiencia y los accesorios se consiguen en partidas con preguntas oficiales.'));return section;}

function renderSpecial(parent,q){const me=state.players.find(p=>p.id===playerId);if(renderPartyExtra(parent,q,me))return true;if(state.excluded?.includes(playerId)){parent.append(el('p','feedback','Esta pregunta la conoces. ¡Anima a los demás!'));return true;}if(state.partyStage==='bet'){parent.append(el('p','sub','Categoría: '+q.category+' · Arriesga únicamente puntos del concurso.'));if(!canPlay()){parent.append(el('p','feedback','Los concursantes están decidiendo.'));return true;}if(me?.betPlaced){parent.append(el('p','feedback','¡Decisión guardada!'));return true;}const max=Math.min(500,Math.max(0,me?.score||0)),slider=el('input'),amount=el('strong','bet-value','0 puntos');slider.type='range';slider.min=0;slider.max=max;slider.step=1;slider.value=0;slider.oninput=()=>amount.textContent=slider.value+' puntos';parent.append(amount,slider,button('Confirmar','primary full',async()=>{try{await send('bet',{amount:Number(slider.value),questionId:q.id});parent.replaceChildren(el('p','feedback','¡Decisión guardada!'));}catch(e){toast(e.message);}}));return true;}if(q.party==='buzzer'&&state.partyStage==='buzz'){const b=button('¡PULSA!','giant-buzzer',async()=>{try{await send('buzz',{questionId:q.id});}catch(e){toast(e.message);}});b.disabled=!canPlay()||!!me?.answered;parent.append(el('p','sub','El primero en pulsar gana el turno. Si falla, otro puede robarlo.'),b);return true;}if(q.party==='buzzer'&&state.buzzer!==playerId){const p=state.players.find(x=>x.id===state.buzzer);parent.append(el('p','feedback',(p?.name||'Un concursante')+' tiene el turno.'));if(role!=='screen')return true;}return false;}
function dialogBox(title){const d=el('dialog','tv-dialog');const inner=el('div','stack');inner.append(el('h2','',title));d.append(inner);document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();return {d,inner};}
function proposalDialog(){const {d,inner}=dialogBox('Tu pregunta secreta');const q=el('textarea');q.maxLength=180;q.placeholder='Escribe una pregunta con una respuesta comprobable';inner.append(el('p','footnote','Máximo 2 por jugador. Solo el anfitrión revisa las propuestas. Tú y el anfitrión no puntuáis en las preguntas que conozcáis.'),q);const opts=[],correct=el('select');for(let i=0;i<4;i++){const inp=el('input');inp.maxLength=80;inp.placeholder='Respuesta '+String.fromCharCode(65+i);opts.push(inp);inner.append(inp);const o=el('option','','Correcta: '+String.fromCharCode(65+i));o.value=i;correct.append(o);}inner.append(correct,button('Enviar al anfitrión','primary full',async()=>{try{await send('propose',{prompt:q.value,options:opts.map(x=>x.value),correct:Number(correct.value)});d.close();toast('Propuesta enviada.');}catch(e){toast(e.message);}}),button('Cancelar','ghost',()=>d.close()));}
async function reviewDialog(){const {d,inner}=dialogBox('Revisión de preguntas');const list=el('div','stack');inner.append(list,button('Cerrar','ghost',()=>d.close()));async function load(){list.replaceChildren(el('p','sub','Cargando…'));try{const {proposals}=await send('review');list.replaceChildren();if(!proposals.length)list.append(el('p','sub','Todavía no hay propuestas.'));for(const x of proposals){const item=el('article','proposal-item');item.append(el('b','',x.name+' · '+x.question.prompt),el('p','sub',x.question.options.map((o,i)=>(i===x.question.correct?'✓ ':'')+o).join(' / ')),el('small','',({pending:'Pendiente',approved:'Aprobada',rejected:'Rechazada'})[x.status]));const decide=async status=>{try{await send('approve',{id:x.id,status});await load();}catch(e){toast(e.message);}};item.append(button('Aceptar','secondary',()=>decide('approved')),button('Descartar','ghost',()=>decide('rejected')));list.append(item);}}catch(e){list.replaceChildren(el('p','error',e.message));}}await load();}

function renderPartyExtra(parent,q,me){const stage=state.partyStage,act=(event,data)=>send(event,{...data,questionId:q.id});const wait=msg=>parent.replaceChildren(el('p','feedback',msg));const targetPicker=(event,verb)=>{const grid=el('div','party-targets');for(const p of state.players.filter(p=>p.id!==playerId)){const b=button('','party-target',async()=>{try{await act(event,{target:p.id});wait('¡Enviado!');}catch(e){toast(e.message);}});b.append(avatarNode(p.avatar,p.name),el('b','',p.name));grid.append(b);}parent.append(el('p','sub',verb),grid);};if(stage==='bluff-write'){parent.append(el('p','sub','Inventa una respuesta falsa que parezca verdadera.'));if(!canPlay()||me?.bluffWritten){parent.append(el('p','feedback','Los farsantes están escribiendo…'));return true;}const input=el('input');input.maxLength=80;input.placeholder='Tu respuesta inventada';parent.append(input,button('Enviar mi mentira','primary full',async()=>{try{await act('bluff',{text:input.value});wait('¡Mentira enviada!');}catch(e){toast(e.message);}}));return true;}if(stage==='bluff-vote'){parent.append(el('p','sub','Encuentra la respuesta verdadera. No votes por la tuya.'));if(me?.voted){wait('¡Voto registrado!');return true;}const grid=el('div','options');for(const o of state.bluffOptions){const b=button(o.text,'option',async()=>{try{await act('vote',{choice:o.id});wait('¡Voto registrado!');}catch(e){toast(e.message);}});b.disabled=!canPlay();grid.append(b);}parent.append(grid);return true;}if(stage==='hot-answer'||stage==='hot-pass'){const holder=state.players.find(p=>p.id===state.hotHolder);parent.append(el('div','hot-potato','🥔'),el('p','feedback',(holder?.name||'Un concursante')+' tiene la patata caliente'));if(stage==='hot-pass'){if(canPlay()&&playerId===state.hotHolder)targetPicker('pass','¡Pásasela a alguien antes de que se acabe el tiempo!');return true;}return playerId!==state.hotHolder&&role!=='screen';}if(stage==='pie-target'){parent.append(el('div','pie-icon','🥧'));if(canPlay()&&me?.canThrow&&!me.pieThrown)targetPicker('pie','¡Elige a quién lanzar tu tarta!');else parent.append(el('p','feedback','Los acertantes preparan las tartas…'));return true;}return false;}
function updatePartyStatus(){const p=state.players.find(x=>x.id===playerId),a=$('#answers');if(!a||!p||state.phase!=='question')return;const sent=state.partyStage==='bluff-write'?p.bluffWritten:state.partyStage==='bluff-vote'?p.voted:state.partyStage==='pie-target'?p.pieThrown:false;if(sent&&!a.dataset.partyLocked){a.dataset.partyLocked='1';a.replaceChildren(el('p','feedback','¡Listo! Esperando al resto…'));}}

let presenterKey='',lastLeader=null,lastPresenterText='';
function presenterUpdate(){const label=$('#presenter-line .presenter-speech');if(!label)return;const k=[state.code,state.index,state.phase,state.partyStage,state.buzzer,state.hotHolder].join(':');if(k===presenterKey){label.textContent=lastPresenterText;return;}presenterKey=k;const leader=state.players[0],q=state.question;let text='';if(state.phase==='lobby')text='¡Bienvenidos al plató! Preparad los pulsadores.';else if(state.phase==='finished')text=leader?'¡Enhorabuena, '+leader.name+'! ¡Menudo concurso!':'¡Hasta la próxima!';else if(state.phase==='reveal'){const hit=state.players.filter(p=>p.hits).sort((a,b)=>b.hits-a.hits)[0];if(hit)text='¡Tartazo para '+hit.name+'! Esto se está poniendo interesante.';else if(q?.party==='bluff'){const best=state.players.filter(p=>p.fooled).sort((a,b)=>b.fooled-a.fooled)[0];text=best?'¡'+best.name+' ha conseguido colar su mentira!':'¡Hoy nadie se ha dejado engañar!';}else if(lastLeader&&leader&&lastLeader!==leader.id)text='¡Tenemos nuevo líder! '+leader.name+' toma la delantera.';else if(state.players.some(p=>p.reaction==='correct'))text=['¡Qué nivel tenemos hoy!','¡Eso sí que es estar atento!','¡Bien jugado! Todavía queda concurso.'][Math.max(0,state.index)%3];else text='¡Venga, la próxima es vuestra!';if(leader)lastLeader=leader.id;}else if(state.partyStage==='intro')text=roundRule(q?.party)?.hint||'¡Preparad los mandos! Nueva ronda.';else if(state.partyStage==='bluff-write')text='Inventad una respuesta que parezca de verdad. ¡A ver quién cuela la mejor!';else if(state.partyStage==='bluff-vote')text='¡Una de estas respuestas es real! ¿Os fiáis de vuestros amigos?';else if(state.partyStage==='hot-answer')text='¡'+(state.players.find(p=>p.id===state.hotHolder)?.name||'Alguien')+' tiene la patata! ¡Corre!';else if(state.partyStage==='hot-pass')text='¡Pásasela a otro concursante!';else if(state.partyStage==='pie-target')text='¡Hora de las tartas! Elegid vuestro objetivo.';else if(state.partyStage==='bet')text='¿Cuántos puntos os atrevéis a arriesgar?';else if(state.partyStage==='buzz')text='¡Manos sobre el pulsador!';else text='¡Vamos con la siguiente!';label.textContent=lastPresenterText=text;}

async function openWardrobe(){if(state&&(state.phase!=='lobby'||!canPlay()))return toast('El vestuario está disponible antes de empezar.');setView('wardrobe');navRender();root.append(el('p','sub','Preparando tu personaje…'));try{const {user:u,progression}=await api('/api/me');if(view!=='wardrobe'||state&&state.phase!=='lobby')return;wardrobe({user:u,progression,save:async data=>{if(state&&state.phase!=='lobby')throw Error('El concurso ya ha empezado.');const result=await api('/api/profile',data);user=result.user;if(state){await send('join',{code:state.code,role});renderRoom();}else await profile();toast('¡Personaje preparado!');},close:()=>state?renderRoom():profile()});}catch(e){toast(e.message);renderRoom();}}

function renderArcade(parent,q,revealed){if(!['memory','odd','reflex','count','number-hunt'].includes(q.party))return false;const me=state.players.find(p=>p.id===playerId);if(['memory','count'].includes(q.party)){if(state.partyStage==='memory-show'&&!revealed){parent.append(el('p','sub','¡Memoriza!'),put(el('div',q.party==='count'?'count-board':'memory-strip'),...(q.preview||[]).map(s=>el('span','memory-symbol',s))));return true;}return false;}if(q.party==='number-hunt'){if(revealed){parent.append(el('p','feedback','¡Fin de la escalera!'));return true;}const chosen=[];const grid=el('div','odd-grid number-hunt');for(const [i,v] of q.options.entries()){const b=button(v,'odd-tile',()=>{if(chosen.includes(i))return;chosen.push(i);b.disabled=true;b.classList.add('cleared');if(chosen.length===q.options.length)submitAnswer(chosen);});b.disabled=!canPlay()||!!me?.answered;grid.append(b);}parent.append(grid,el('p','sub','Pulsa todos los números de menor a mayor.'));return true;}if(revealed){parent.append(el('div','result',q.party==='reflex'?'¡Fin de la carrera de reflejos!':'¡Este era el símbolo diferente!'));if(q.party==='odd')parent.append(el('div','memory-symbol',q.options[q.correct]));return true;}if(me?.answered){parent.append(el('p','feedback','¡Intento registrado!'));return true;}if(q.party==='reflex'){const go=state.partyStage==='reflex-go';const b=button(go?'¡YA!':'ESPERA…','reflex-pad '+(go?'go':'wait'),()=>{b.disabled=true;navigator.vibrate?.(30);submitAnswer(0);});b.disabled=!canPlay();parent.append(b,el('p','sub','Pulsar antes de la señal cuenta como intento fallido.'));return true;}const grid=el('div','odd-grid');for(const [i,v] of q.options.entries()){const b=button(v,'odd-tile',()=>{b.classList.add('pad-fired');submitAnswer(i);});b.disabled=!canPlay();grid.append(b);}parent.append(grid);return true;}

function renderDrawing(parent,q,revealed){const isDrawer=canPlay()&&playerId===state.drawer&&!revealed,drawer=state.players.find(p=>p.id===state.drawer);const board=createDrawBoard({drawer:isDrawer,questionId:q.id,send,secret:()=>send('draw-secret',{questionId:q.id})});board.id='live-drawing';board.update(state.strokes||[]);parent.append(el('p','sub',(drawer?.name||'Un concursante')+' está dibujando'),board);if(revealed){parent.append(el('div','result','La palabra era: '+q.correct));return;}if(isDrawer){parent.append(el('p','sub','No escribas letras ni números. ¡Que tus amigos lo adivinen!'));return;}if(!canPlay())return;const input=el('input');input.id='drawing-guess';input.maxLength=64;input.placeholder='¿Qué está dibujando?';const status=el('p','sub');status.id='drawing-status';const b=button('Adivinar','primary full',async()=>{if(!input.value.trim()||b.disabled||input.disabled)return;b.disabled=true;try{const r=await send('draw-guess',{questionId:q.id,text:input.value});if(r.correct){status.textContent='¡Lo has adivinado!';input.disabled=true;}else{status.textContent='¡Sigue intentándolo!';input.value='';input.focus();}}catch(e){status.textContent=e.message;}finally{b.disabled=false;}});input.onkeydown=e=>{if(e.key==='Enter')b.click();};parent.append(input,b,status);}

function statsShareControl(){const me=state.players.find(p=>p.id===playerId),input=el('input');input.type='checkbox';input.checked=!!me?.shareStats;const label=put(el('label','play-toggle share-stats'),input,put(el('span'),el('b','','Compartir mi historial con esta sala'),el('small','','Tus amigos podrán consultar tu nivel, logros y estadísticas globales. Los resultados de esta partida siempre son visibles para sus participantes.')));input.onchange=async()=>{input.disabled=true;try{await send('share-stats',{share:input.checked});toast(input.checked?'Historial compartido en esta sala.':'Historial privado.');}catch(e){input.checked=!input.checked;toast(e.message);}finally{input.disabled=false;}};return label;}
async function openPlayerCard(p){if(!state||state.phase!=='finished'||role==='screen')return;const old=$('#friend-profile');if(old?.open){old.close();}const dialog=el('dialog','friend-profile');dialog.id='friend-profile';dialog.dataset.match=state.matchId;dialog.setAttribute('aria-label','Ficha de '+p.name);const close=button('← Volver a la clasificación','ghost',()=>dialog.close());const content=el('div','friend-profile-content');content.append(el('p','sub','Cargando ficha…'));dialog.append(close,content);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();try{const data=await api('/api/rooms/'+state.code+'/player-card',{playerId:p.id,matchId:dialog.dataset.match});if(!dialog.open)return;content.replaceChildren();const hero=el('div','friend-profile-hero');hero.append(avatarNode(data.avatar,data.name),put(el('div'),el('div','tag','FICHA DEL CONCURSANTE'),el('h2','',data.name),el('p','sub',data.progress?'Nivel '+data.progress.level+' · '+data.progress.xp.toLocaleString('es-ES')+' XP':'Resultados del concurso')));content.append(hero);const addStats=(title,s,career)=>{const section=el('section','friend-stat-section');section.append(el('h3','',title));const grid=el('div','friend-metrics');metric(grid,'Aciertos',s.total?s.accuracy+'%':'—',s.correct+' de '+s.total+' rondas');metric(grid,career?'Récord':'Puntos',(career?s.bestScore:data.score).toLocaleString('es-ES'),'Puntuación');metric(grid,'Rapidez',s.avgMs===null?'—':(s.avgMs/1000).toFixed(1)+' s','Tiempo medio');if(career)metric(grid,'Victorias',String(s.wins),s.matches+' partidas');section.append(grid);const cats=el('div','friend-categories');for(const c of s.byCategory||[]){const row=el('div','friend-category-row'),bar=el('div','friend-bar');bar.style.setProperty('--category',categoryArt(c.name).color);const fill=el('i');fill.style.width=c.accuracy+'%';bar.append(fill);row.append(categoryBadge(c.name),el('strong','',c.correct+'/'+c.total),bar);cats.append(row);}section.append(cats);if(s.byDifficulty?.length)section.append(bars('Por dificultad',s.byDifficulty));content.append(section);};addStats('En esta partida',data.matchStats,false);if(data.career){addStats('Trayectoria',data.career,true);const unlocked=data.progress?.achievements.filter(x=>x.unlocked)||[];if(unlocked.length){const achievements=el('div','friend-achievements');achievements.append(el('h3','','Logros desbloqueados'));unlocked.forEach(x=>achievements.append(put(el('div','award'),el('b','',x.name),el('small','',x.label))));content.append(achievements);}}else content.append(el('p','footnote','Este concursante ha elegido mantener privado su historial global.'));}catch(e){if(dialog.open)content.replaceChildren(el('p','error',e.message));}}

function emoteSettings(u,progress){if(state&&!['lobby','finished'].includes(state.phase)){toast('Puedes cambiar tus emotes al acabar la partida.');return;}const d=el('dialog','emote-settings'),selection=cleanEmotes(u.avatar?.emotes),preview=el('div','emote-preview'),status=el('p','footnote','Elige qué hará tu personaje. Los emotes bloqueados muestran cómo conseguirlos.');const refresh=(pose)=>{preview.replaceChildren(avatarNode(u.avatar,u.name));mountCharacter(preview,u.avatar,pose==='random'?'disco':pose);};d.append(el('h2','','Mis emotes'),preview,status);for(const [kind,title] of [['good','Cuando acierto'],['bad','Cuando fallo']]){const group=el('section','emote-options');group.append(el('h3','',title));const grid=el('div','emote-grid'),allowed=allowedEmotes(progress,kind);for(const [id,label] of Object.entries(emotes[kind])){const locked=!allowed.includes(id),b=button(label,'emote-choice',()=>{refresh(id);if(locked){status.textContent=emoteRewards.find(r=>r.item===id)?.description||'Emote bloqueado';return;}selection[kind]=id;grid.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));status.textContent=label+' seleccionado.';});b.setAttribute('aria-pressed',String(selection[kind]===id));if(locked){b.classList.add('locked');b.append(el('small','','🔒 '+(emoteRewards.find(r=>r.item===id)?.description||'Bloqueado')));}grid.append(b);}group.append(grid);d.append(group);}const save=button('Guardar emotes','primary full',async()=>{save.disabled=true;try{const result=await api('/api/emotes',selection);user=result.user;if(state?.phase==='lobby'&&canPlay())await send('join',{code:state.code,role});d.close();navRender();toast('¡Emotes guardados!');if(view==='profile')profile();}catch(e){status.textContent=e.message;save.disabled=false;}});d.append(save,button('Cancelar','ghost',()=>d.close()));document.body.append(d);d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();refresh(selection.good);}

// A read-only television has no scroll controls. Fit long questions, media and options into the available panel.
function fitTvQuestion(panel,content){let frame,observer,mutations;const fit=()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(!panel.isConnected)return;content.style.transform='none';const available=panel.clientHeight-parseFloat(getComputedStyle(panel).paddingTop)-parseFloat(getComputedStyle(panel).paddingBottom),height=content.scrollHeight;if(available>0&&height>available+2){const scale=Math.max(.25,available/height);content.style.transform='scale('+scale+')';}});};fit();if(window.ResizeObserver){observer=new ResizeObserver(fit);observer.observe(panel);observer.observe(content);}if(window.MutationObserver){mutations=new MutationObserver(fit);mutations.observe(content,{childList:true,subtree:true,characterData:true});}const detach=new MutationObserver(()=>{if(!panel.isConnected){observer?.disconnect();mutations?.disconnect();detach.disconnect();cancelAnimationFrame(frame);}});detach.observe(root,{childList:true,subtree:true});content.querySelectorAll('img,video').forEach(m=>{m.addEventListener('load',fit);m.addEventListener('loadedmetadata',fit);});document.fonts?.ready.then(fit);}

function makeDifficultyPicker(){const node=el('section','mode-setting difficulty-picker'),header=el('div','difficulty-heading'),value=el('strong','difficulty-value'),hint=el('p','difficulty-hint'),rail=el('div','difficulty-rail'),choices=el('div','difficulty-choices'),range=el('input','difficulty-range'),mix=button('🎲  Mezclar niveles','difficulty-mix',()=>choose('Mixta'));let selected='Media';header.append(el('span','setup-section-label','02 / DIFICULTAD'),value);range.type='range';range.min=0;range.max=4;range.step=1;range.value=2;range.setAttribute('aria-label','Dificultad de muy fácil a muy difícil');rail.append(range);const buttons=levels.map((l,i)=>{const b=button('','difficulty-stop',()=>choose(l.id));b.style.setProperty('--level-color',l.color);b.append(el('span','difficulty-icon',l.icon),el('b','',l.label));choices.append(b);return b;});function choose(id){selected=id;const i=levels.findIndex(l=>l.id===id),l=levels[i];if(l)range.value=String(i);range.setAttribute('aria-valuetext',l?.label||'Mixta');node.style.setProperty('--level-color',l?.color||'#c5a9ff');value.textContent=l?l.icon+' '+l.label:'🎲 Mixta';hint.textContent=l?.hint||'Una combinación de preguntas de todos los niveles.';buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(i===j)));mix.setAttribute('aria-pressed',String(i<0));rail.classList.toggle('mixed',i<0);}range.oninput=()=>choose(levels[Number(range.value)].id);node.append(header,rail,choices,hint,mix);choose('Media');return {node,get value(){return selected;}};}
function makeThemePicker(){const node=el('section','mode-setting theme-picker'),grid=el('div','theme-grid');let selected='neon';node.append(el('span','setup-section-label','03 / ELIGE EL PLATÓ'),grid);for(const [id,label,icon] of [['neon','Neón','✦'],['space','Espacial','🪐'],['tropical','Tropical','🌴'],['retro','Retro','👾']]){const b=button('','theme-card',()=>{selected=id;for(const x of grid.children)x.setAttribute('aria-pressed',String(x===b));});b.dataset.theme=id;b.setAttribute('aria-pressed',String(id===selected));b.append(el('span','theme-art',icon),el('b','',label),el('span','theme-check','✓'));grid.append(b);}return {node,get value(){return selected;}};}

function haptic(pattern){try{navigator.vibrate?.(pattern);}catch{}}
function makeAnswerReceipt(me){const receipt=el('div','answer-receipt');receipt.setAttribute('role','status');receipt.append(el('span','receipt-tick','✓'),el('strong','','¡Respuesta registrada!'),el('p','',state.solo?'Tu respuesta está guardada.':'El resto de concursantes sigue jugando.'),el('span','receipt-score',(me?.score||0).toLocaleString('es-ES')+' PTS'));return receipt;}
function renderRoundIntro(main){const q=state.question;if(!q)return;const stage=el('div','round-intro broadcast-intro'),meta=el('div','intro-meta'),scene=showScene(state);stage.dataset.finale=String(scene.finale);stage.append(el('div','broadcast-eyebrow',scene.tag));stage.style.setProperty('--intro-color',scene.theme);meta.append(el('span','','RONDA '+String(state.index+1).padStart(2,'0')+' / '+state.total),difficultyBadge(q.difficulty));const mark=categoryBadge(q.category);mark.classList.add('intro-category');const ring=el('div','intro-count-ring'),clock=el('strong','',String(Math.max(1,Math.ceil((state.deadline-Date.now()-offset)/1000))));clock.id='clock';ring.append(clock);const meter=el('mq-round-meter');meter.id='timebar';meter.setAttribute('progress','100');const rule=roundRule(q.party),label=scene.finale&&q.party!=='final'?scene.title:rule?.title||(isAction(q.party)?actionMeta[q.party].title:scene.opening&&state.kind!=='arcade'?'¡QUE EMPIECE EL SHOW!':scene.title);stage.dataset.rule=q.party||'classic';stage.append(meta,el('div','intro-title',label),mark,ring,meter,el('p','intro-sub',rule?.hint||(isAction(q.party)?actionMeta[q.party].subtitle:scene.subtitle)));if(state.kind==='party'&&state.playlist?.length&&(state.introDuration||3000)>=3000)stage.append(roundJourney(state));main.append(stage);}
function updateConnectionUI(){const status=socket?.status;let banner=$('#connection-indicator');if(!state||!role||status==='connected'||!status){banner?.remove();return;}if(!banner){banner=el('div','connection-indicator');banner.id='connection-indicator';banner.setAttribute('role','status');document.body.append(banner);}banner.textContent=status==='expired'?'La sala ha caducado. Vuelve al inicio.':status==='connecting'?'Conectando al plató…':'Reconectando al plató… No cierres el juego.';banner.dataset.status=status;}
window.addEventListener('online',()=>{if(socket&&!socket.closed){clearTimeout(socket.timer);socket.open();}});window.addEventListener('offline',()=>socket?.setStatus('reconnecting'));

function showUnlockCelebration(achievements,level){document.querySelector('.unlock-celebration')?.remove();const banner=el('aside','unlock-celebration');banner.setAttribute('role','status');banner.append(el('span','unlock-medal','★'),el('strong','',level?'¡NIVEL '+level+'!':'¡LOGRO DESBLOQUEADO!'));for(const a of achievements.slice(0,3))banner.append(el('b','',a.name),el('small','','Recompensa: '+a.label));if(achievements.length>3)banner.append(el('small','','+'+(achievements.length-3)+' logros más en tu perfil'));banner.append(button('Cerrar','ghost',()=>banner.remove()));document.body.append(banner);playSound('rank');confetti(banner);setTimeout(()=>banner.remove(),8500);}

function resultCaption(q){if(!q||isAction(q.party)||['reflex','odd','memory','count','number-hunt'].includes(q.party))return '¡Prueba terminada!';if(q.party==='draw')return 'La palabra era: '+q.correct;if(q.party==='bluff')return 'La respuesta era: '+q.correct;if(q.party==='estimate')return 'La cifra real: '+Number(q.correct).toLocaleString('es-ES',{maximumFractionDigits:6});try{const label=answerLabel(q);return label===undefined||label===null||label==='undefined'?'¡Ronda terminada!':'Respuesta: '+label;}catch{return '¡Ronda terminada!';}}

function roundRule(party){return ({warmup:{title:'CALENTAMIENTO',hint:'Cuatro opciones. Acierta cuanto antes.'},'order-round':{title:'PONLO EN ORDEN',hint:'Ordena los elementos y confirma antes de que acabe el tiempo.'},estimate:{title:'LA CIFRA JUSTA',hint:state?.solo?'Acércate lo máximo posible a la cifra real.':'La cifra más cercana gana 1.000 puntos.'},buzzer:{title:'EL GRAN PULSADOR',hint:'Lee la pregunta, pulsa primero y responde.'},steal:{title:'ROBAPUNTOS',hint:'El acierto más rápido roba hasta 400 puntos al rival mejor situado (máximo 20 %).'},final:{title:'GRAN FINAL · ×'+(state?.question?.multiplier||2),hint:state?.question?.multiplier===3?'Última oportunidad: ¡cada acierto vale el triple!':'¡Todos los aciertos valen el doble!'},'solo-bonus':{title:'BONUS INDIVIDUAL · ×1,5',hint:'Acierta y consigue un 50 % más de puntos.'},wager:{title:'LA GRAN SUBASTA',hint:'Arriesga parte de tus puntos antes de ver la pregunta.'},bluff:{title:'EL FARSANTE',hint:'Inventa una mentira y encuentra la respuesta verdadera.'},hot:{title:'PATATA CALIENTE',hint:'Responde bien y pasa el turno.'},pie:{title:'TARTAZO',hint:'Acierta para lanzar una tarta a un rival.'}})[party];}

function roundJourney(s){const wrap=el('div','round-journey'),track=el('div','round-journey-track'),label=el('div','journey-label');wrap.setAttribute('aria-label','Recorrido del Gran Concurso');const descriptors={warmup:['●','Calentamiento','#79c9ff'],'order-round':['↕','Orden','#c9b6ff'],estimate:['≈','Cifra justa','#77e2b2'],buzzer:['⚡','Pulsador','#ffd55a'],wager:['±','Subasta','#ffbf82'],bluff:['?','Farsante','#d3a3ff'],hot:['!','Patata','#ffa971'],pie:['✦','Tartazo','#ffb1ba'],draw:['✎','Dibujo','#9ed8ff'],steal:['↔','Robapuntos','#ff829d'],final:['×3','Gran final','#ffd55a'],'solo-bonus':['×1,5','Bonus','#ff829d'],custom:['★','Amigos','#aeeed1']};const groups=[];for(const [i,party] of (s.playlist||[]).entries()){const last=groups[groups.length-1];if(last?.party===party)last.end=i;else groups.push({party,start:i,end:i});}if(!groups.length)return wrap;const current=groups.findIndex(g=>s.index>=g.start&&s.index<=g.end);label.textContent=current<0?'EL RECORRIDO DEL CONCURSO':'BLOQUE '+(current+1)+' / '+groups.length;for(const [i,g] of groups.entries()){const [symbol,name,color]=descriptors[g.party]||['•','Ronda','#d7c7e9'],step=el('div','journey-stop');step.style.setProperty('--journey-color',color);step.dataset.status=current===i?'current':current>i?'done':'next';step.append(el('b','journey-symbol',current>i?'✓':symbol),el('span','journey-name',name),el('small','journey-count',String(g.end-g.start+1)));step.setAttribute('aria-label',name+', '+(g.end-g.start+1)+' preguntas'+(current===i?', bloque actual':''));if(current===i)step.setAttribute('aria-current','step');track.append(step);}wrap.append(label,track);return wrap;}
